// Call widget Sample widget (public endpoint, rate limited to 10 requests/min per IP)
// Node 18+ (global fetch). Run with: npx tsx swfte-call.ts
const BASE_URL = "https://api.example.test/agents";
const headers: Record<string, string> = {
  "Content-Type": "application/json",
};

async function main() {
  const res = await fetch(`${BASE_URL}/v1/widgets/widget_1/public/invoke`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      "input": {
        "message": "Hello"
      }
    }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  console.log(data["response"]);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
